def latest_records(rows):
    latest = {}
    for row in rows:
        key = row["entity_id"]
        previous = latest.get(key)
        if previous is None or row["updated_at"] >= previous["updated_at"]:
            latest[key] = row
    return latest

def latest_records_alternative(rows):
    ordered = sorted(rows, key=lambda row: row["updated_at"])
    return {row["entity_id"]: row for row in ordered}
